using NUnit.Framework;

namespace Unitas.Samples.RollABall.Tests
{
    public class BonusPickupTests
    {
        private const int BonusBaseScore = 5;

        [Test]
        public void BonusPickupAwardsFivePointsAtBaseMultiplier()
        {
            int awarded = BonusBaseScore * 1;
            Assert.AreEqual(5, awarded);
        }

        [Test]
        public void BonusPickupScalesAwardWithComboMultiplier()
        {
            int awarded = BonusBaseScore * 3;
            Assert.AreEqual(15, awarded);
        }
    }
}
